import{_ as a,o as s,c as i,a4 as t}from"./chunks/framework.vNSRaLQv.js";const k=JSON.parse('{"title":"Docker 桌面图标折腾记录","description":"","frontmatter":{"title":"Docker 桌面图标折腾记录","date":"2026-08-12T00:00:00.000Z"},"headers":[],"relativePath":"posts/Docker桌面图标折腾记录_2026-08-12.md","filePath":"posts/Docker桌面图标折腾记录_2026-08-12.md"}'),o={name:"posts/Docker桌面图标折腾记录_2026-08-12.md"};function d(n,e,r,l,c,h){return s(),i("div",null,[...e[0]||(e[0]=[t(`<h1 id="docker-桌面图标折腾记录" tabindex="-1">Docker 桌面图标折腾记录 <a class="header-anchor" href="#docker-桌面图标折腾记录" aria-label="Permalink to &quot;Docker 桌面图标折腾记录&quot;">​</a></h1><p><strong>日期</strong>: 2026-08-12</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>给 Docker 桌面快捷方式加图标，SVG 格式不显示，PNG 格式正常。</p><h2 id="排查过程" tabindex="-1">排查过程 <a class="header-anchor" href="#排查过程" aria-label="Permalink to &quot;排查过程&quot;">​</a></h2><h3 id="_1-尝试系统图标" tabindex="-1">1. 尝试系统图标 <a class="header-anchor" href="#_1-尝试系统图标" aria-label="Permalink to &quot;1. 尝试系统图标&quot;">​</a></h3><ul><li><code>Icon=docker</code> → 空白（图标名未注册）</li><li><code>Icon=yast-docker</code> → 空白（符号链接到 preferences-virtualization-container，不是 Docker 鲸鱼）</li><li><code>Icon=folder-docker</code> → 空白（图标名未在 index.theme 注册）</li><li><code>Icon=/usr/share/icons/breeze/places/64/folder-docker.svg</code> → 显示了文件夹套鲸鱼（KDE 能识别完整路径的 SVG）</li></ul><h3 id="_2-尝试自定义-svg" tabindex="-1">2. 尝试自定义 SVG <a class="header-anchor" href="#_2-尝试自定义-svg" aria-label="Permalink to &quot;2. 尝试自定义 SVG&quot;">​</a></h3><p>用户提供的 <code>text-dockerfile.svg</code>（Docker 鲸鱼）：</p><ul><li><code>Icon=/home/a1/sh/docker/docker.svg</code> → 不显示</li><li>测试 .desktop 也不显示</li></ul><h3 id="_3-根因定位" tabindex="-1">3. 根因定位 <a class="header-anchor" href="#_3-根因定位" aria-label="Permalink to &quot;3. 根因定位&quot;">​</a></h3><p>SVG 文件里有 Inkscape 特有标签（<code>sodipodi</code>、<code>inkscape</code>），KDE 的 SVG 渲染器（librsvg）无法解析：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes vitesse-light vitesse-dark vp-code" style="--shiki-light:#393a34;--shiki-dark:#dbd7caee;--shiki-light-bg:#ffffff;--shiki-dark-bg:#121212;" tabindex="0"><code><span class="line"><span>有 Inkscape 标签 → 40 处</span></span>
<span class="line"><span>能显示的 SVG → 0 处 Inkscape 标签</span></span></code></pre></div><p>rsvg-convert 也报错：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes vitesse-light vitesse-dark vp-code" style="--shiki-light:#393a34;--shiki-dark:#dbd7caee;--shiki-light-bg:#ffffff;--shiki-dark-bg:#121212;" tabindex="0"><code><span class="line"><span>Error reading SVG: XML parse error: Attribute inkscape:connector-curvature redefined</span></span></code></pre></div><h3 id="_4-解决方案" tabindex="-1">4. 解决方案 <a class="header-anchor" href="#_4-解决方案" aria-label="Permalink to &quot;4. 解决方案&quot;">​</a></h3><p>去掉 Inkscape 标签，保留纯 SVG 路径，再转 PNG：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes vitesse-light vitesse-dark vp-code" style="--shiki-light:#393a34;--shiki-dark:#dbd7caee;--shiki-light-bg:#ffffff;--shiki-dark-bg:#121212;" tabindex="0"><code><span class="line"><span style="--shiki-light:#A0ADA0;--shiki-dark:#758575DD;"># 清理后的 SVG 转 PNG</span></span>
<span class="line"><span style="--shiki-light:#59873A;--shiki-dark:#80A665;">rsvg-convert</span><span style="--shiki-light:#A65E2B;--shiki-dark:#C99076;"> -w</span><span style="--shiki-light:#2F798A;--shiki-dark:#4C9A91;"> 256</span><span style="--shiki-light:#A65E2B;--shiki-dark:#C99076;"> -h</span><span style="--shiki-light:#2F798A;--shiki-dark:#4C9A91;"> 256</span><span style="--shiki-light:#B56959;--shiki-dark:#C98A7D;"> docker-clean.svg</span><span style="--shiki-light:#A65E2B;--shiki-dark:#C99076;"> -o</span><span style="--shiki-light:#B56959;--shiki-dark:#C98A7D;"> docker.png</span></span></code></pre></div><h2 id="最终配置" tabindex="-1">最终配置 <a class="header-anchor" href="#最终配置" aria-label="Permalink to &quot;最终配置&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes vitesse-light vitesse-dark vp-code" style="--shiki-light:#393a34;--shiki-dark:#dbd7caee;--shiki-light-bg:#ffffff;--shiki-dark-bg:#121212;" tabindex="0"><code><span class="line"><span>/home/a1/sh/docker/docker.svg    ← 原始 SVG（有 Inkscape 标签，KDE 不认）</span></span>
<span class="line"><span>/home/a1/sh/docker/docker.png    ← 清理后转的 PNG（KDE 正常显示）</span></span>
<span class="line"><span>/home/a1/sh/docker/docker-toggle.sh</span></span>
<span class="line"><span>/home/a1/桌面/docker-toggle.desktop → Icon=/home/a1/sh/docker/docker.png</span></span></code></pre></div><h2 id="关键结论" tabindex="-1">关键结论 <a class="header-anchor" href="#关键结论" aria-label="Permalink to &quot;关键结论&quot;">​</a></h2><table tabindex="0"><thead><tr><th>格式</th><th>KDE 支持</th><th>Inkscape SVG</th><th>纯 SVG</th></tr></thead><tbody><tr><td>SVG</td><td>⚠️ 要求纯 SVG</td><td>❌ 不显示</td><td>✅ 显示</td></tr><tr><td>PNG</td><td>✅ 通用</td><td>-</td><td>-</td></tr></tbody></table><p><strong>KDE 图标用 PNG 最稳，SVG 要确保没有 Inkscape/sodipodi 标签。</strong></p><h2 id="工具" tabindex="-1">工具 <a class="header-anchor" href="#工具" aria-label="Permalink to &quot;工具&quot;">​</a></h2><ul><li><code>rsvg-convert</code>（librsvg2-bin）：SVG 转 PNG</li><li><code>kbuildsycoca5</code>：重建 KDE 图标缓存</li></ul>`,25)])])}const g=a(o,[["render",d]]);export{k as __pageData,g as default};
